<template><view v-if="mode === 'article' ? (article.issue || (article.policy_checks || []).length) : mode === 'today' ? (updates.length || error) : true" :class="['ip-entry', mode === 'discover' ? 'ip-entry-discover' : '']"><template v-if="mode === 'article'"><view v-if="article.issue" class="ip-entry-row"><text class="ip-entry-title">所属议题 · {{ article.issue.title }}</text><text class="ip-entry-title">本文是第 {{ article.issue.position }} / {{ article.issue.event_count }} 条进展 · {{ stageLabel(article.issue.stage) }}</text><text class="ip-entry-title">{{ article.issue.status_line }}</text><text v-if="article.issue.prev_delta" class="ip-entry-title">上次进展：{{ article.issue.prev_delta }}</text><button class="ip-entry-button" @click="issue(article.issue.issue_key)">查看议题进展</button><button class="ip-entry-button" :disabled="followBusy" @click="toggleFollow">{{ following ? '取消关注' : '关注议题' }}</button></view><view v-for="item in article.policy_checks || []" :key="item.policy_key" class="ip-entry-row"><text class="ip-entry-title">{{ item.title }}</text><button class="ip-entry-button" @click="policy(item.policy_key)">匿名政策自查</button></view></template><template v-else-if="mode === 'today'"><view v-if="updates.length" class="ip-entry-row"><text class="ip-entry-title">关注议题有 {{ updates.length }} 项新进展</text><button v-for="item in updates" :key="item.issue.issue_key" class="ip-entry-button" @click="issue(item.issue.issue_key)">{{ item.issue.title }} · {{ item.new_events ? item.new_events + ' 条更新' : '议题信息已修订' }}</button></view><text v-if="error" class="ip-entry-title">{{ error }}</text></template><template v-else-if="mode === 'discover'"><view class="ip-portals"><button class="ip-portal ip-portal-track" @click="list"><view class="ip-portal-symbol"><image class="ip-portal-icon" src="/static/icons/issue-track.svg" mode="aspectFit" aria-hidden="true" /></view><text class="ip-portal-name">追踪</text><text class="ip-portal-caption">看懂每一步变化</text><text class="ip-portal-open">↗</text></button><button class="ip-portal ip-portal-check" @click="policies"><view class="ip-portal-symbol"><image class="ip-portal-icon" src="/static/icons/policy-check.svg" mode="aspectFit" aria-hidden="true" /></view><text class="ip-portal-name">自查</text><text class="ip-portal-caption">理清申请资格</text><text class="ip-portal-open">↗</text></button></view><view v-for="item in activeIssues" :key="item.issue_key" class="ip-entry-row"><text class="ip-entry-title">{{ item.title }} · {{ stageLabel(item.stage) }}</text><button class="ip-entry-button" @click="issue(item.issue_key)">查看时间线</button></view></template><template v-else><text class="ip-entry-title">{{ mode === 'mine' ? '持续关注的变化' : '从一篇文章，看到一条脉络' }}</text><view v-if="mode === 'discover'"><view v-for="item in activeIssues" :key="item.issue_key" class="ip-entry-row"><text class="ip-entry-title">{{ item.title }} · {{ stageLabel(item.stage) }}</text><text class="ip-entry-title">{{ item.status_line }}</text><button class="ip-entry-button" @click="issue(item.issue_key)">查看时间线</button></view></view><button class="ip-entry-button" @click="list">{{ mode === 'mine' ? '我关注的议题' : '追踪' }}</button><button v-if="mode !== 'mine'" class="ip-entry-button" @click="policies">自查</button></template></view></template>
<script>
import { stageLabel } from '@/utils/issue-policy.js'
import { getIssueUpdates, getAuthToken, getIssue, followIssue, getIssues } from '@/utils/api.js'
export default { props: { mode: { type: String, default: 'discover' }, article: { type: Object, default: () => ({}) } }, data: () => ({ updates: [], error: '', generation: 0, following: false, followBusy: false, activeIssues: [] }), mounted() { this.refresh() }, watch: { article() { this.refresh() } }, methods: { stageLabel, async toggleFollow() { if (!getAuthToken()) { uni.navigateTo({ url: '/pages/auth/login' }); return } if (this.followBusy) return; this.followBusy = true; try { const result = await followIssue(this.article.issue.issue_key, !this.following); this.following = result.is_following } catch (e) { uni.showToast({ title: e.message, icon: 'none' }) } finally { this.followBusy = false } }, list() { uni.navigateTo({ url: `/pages/issues/index${this.mode === 'mine' ? '?mine=1' : ''}` }) }, policies() { uni.navigateTo({ url: '/pages/policy/index' }) }, policy(key) { uni.navigateTo({ url: `/pages/policy/detail?key=${encodeURIComponent(key)}` }) }, issue(key) { uni.navigateTo({ url: `/pages/issues/detail?key=${encodeURIComponent(key)}` }) }, async refresh() { const generation = ++this.generation; this.updates = []; this.error = ''; if (this.mode === 'article' && this.article.issue) { try { const detail = await getIssue(this.article.issue.issue_key); if (generation === this.generation) this.following = detail.is_following } catch {} return } if (this.mode === 'discover') { try { const items = await getIssues(); if (generation === this.generation) this.activeIssues = items.filter(i => i.stage !== 'ended').slice(0, 6) } catch { this.error = '议题暂时无法加载。' } return } if (this.mode !== 'today' || !getAuthToken()) return; const token = getAuthToken(); try { const data = await getIssueUpdates(); if (generation === this.generation && token === getAuthToken()) this.updates = data } catch (e) { if (generation === this.generation) this.error = '议题更新暂时无法加载，请稍后重试。' } } } }
</script>
<style>
.ip-entry.ip-entry-discover{padding:0;background:transparent;border-radius:0;margin:32rpx 0 48rpx}
.ip-portals{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24rpx}
.ip-portals .ip-portal{position:relative;display:flex;flex-direction:column;align-items:flex-start;justify-content:flex-start;box-sizing:border-box;width:100%;min-height:306rpx;margin:0;padding:32rpx;text-align:left;line-height:1.4;border:0;border-radius:30rpx;color:#24564f;background:#eaf0eb;overflow:hidden;transition:box-shadow 150ms}
.ip-portals .ip-portal::after{border:0}
.ip-portals .ip-portal-check{color:#405d70;background:#eaf0f3}
.ip-portal-symbol{display:flex;align-items:center;justify-content:center;width:76rpx;height:76rpx;margin-bottom:26rpx;border-radius:23rpx;background:#ffffff60;font-size:42rpx;font-weight:400}
.ip-portal-icon{display:block;width:52rpx;height:52rpx;transform:translateY(.125em)}
.dark-mode .ip-portal-icon{filter:brightness(0) saturate(100%) invert(87%) sepia(10%) saturate(450%) hue-rotate(107deg)}
.ip-symbol-track{position:relative;flex-direction:column;gap:12rpx}
.ip-symbol-track::before{content:'';position:absolute;top:20rpx;bottom:20rpx;left:37rpx;width:2rpx;background:currentColor;opacity:.24}
.ip-symbol-track>view{width:8rpx;height:8rpx;border-radius:50%;background:currentColor;z-index:1}
.ip-portal-name{font-size:48rpx;font-weight:500;letter-spacing:.12em}
.ip-portal-caption{margin-top:12rpx;font-size:24rpx;line-height:1.7;opacity:.75;text-wrap:pretty}
.ip-portal-open{position:absolute;right:28rpx;top:24rpx;font-size:36rpx;opacity:.6}
.ip-portals .ip-portal:focus-visible{outline:none;box-shadow:0 0 0 1px #28645e1f,0 0 0 4px #28645e0f}
.dark-mode .ip-portals .ip-portal{background:#283c39;color:#bdd7ce;font-weight:240}
.dark-mode .ip-portals .ip-portal-check{background:#2b3943;color:#c4d6e2}
.dark-mode .ip-portal-name{font-weight:300}
.dark-mode .ip-portal-symbol{background:#ffffff06;font-weight:240}
@media(prefers-reduced-motion:reduce){.ip-portals .ip-portal{transition:none}}
</style>
<style>.ip-entry{margin:28rpx 0;padding:22rpx;background:rgba(113,148,139,.07);border-radius:18rpx}.ip-entry:empty{display:none}.ip-entry-title{display:block;font-size:27rpx;line-height:1.8;text-wrap:pretty}.ip-entry-button{text-align:left;font-size:27rpx;color:#28645e;padding:14rpx 0;line-height:1.7}.dark-mode .ip-entry-button{color:#abd1c8;font-weight:240}.ip-entry-button:focus-visible{outline:none;box-shadow:0 0 0 1px #28645e1f,0 0 0 4px #28645e0f}</style>
